VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-status-badge-padding-block);
    padding-inline: var(--shelf-status-badge-padding-inline);
    border-radius: var(--shelf-status-badge-radius);
    font-size: var(--shelf-status-badge-font-size);
    font-weight: 500;
    background-color: var(--shelf-status-badge-bgColor-default);
    color: var(--shelf-status-badge-fgColor-default);
  }

  .status-badge[data-status="reading"] {
    background-color: var(--shelf-status-badge-bgColor-reading);
    color: var(--shelf-status-badge-fgColor-reading);
  }

  .status-badge[data-status="read"] {
    background-color: var(--shelf-status-badge-bgColor-read);
    color: var(--shelf-status-badge-fgColor-read);
  }

  .status-badge[data-status="to-read"] {
    background-color: var(--shelf-status-badge-bgColor-to-read);
    color: var(--shelf-status-badge-fgColor-to-read);
  }
}
